# Custom REST Service in Dynamics AX (X++)

Below is a comprehensive guide to creating a custom REST service in Dynamics 365 Finance and Operations (D365FO) using X++.

## 1. Create the Data Contract Class

```xpp
/// <summary>
/// Data contract for customer information request
/// </summary>
[DataContractAttribute]
class CustomerInfoRequest
{
    private str customerAccount;
    private str customerName;
    private str customerGroup;

    [DataMemberAttribute('CustomerAccount')]
    public str parmCustomerAccount(str _customerAccount = customerAccount)
    {
        customerAccount = _customerAccount;
        return customerAccount;
    }

    [DataMemberAttribute('CustomerName')]
    public str parmCustomerName(str _customerName = customerName)
    {
        customerName = _customerName;
        return customerName;
    }

    [DataMemberAttribute('CustomerGroup')]
    public str parmCustomerGroup(str _customerGroup = customerGroup)
    {
        customerGroup = _customerGroup;
        return customerGroup;
    }
}
```

## 2. Create the Response Data Contract

```xpp
/// <summary>
/// Data contract for customer information response
/// </summary>
[DataContractAttribute]
class CustomerInfoResponse
{
    private boolean success;
    private str message;
    private str customerId;
    private List customerList;

    [DataMemberAttribute('Success')]
    public boolean parmSuccess(boolean _success = success)
    {
        success = _success;
        return success;
    }

    [DataMemberAttribute('Message')]
    public str parmMessage(str _message = message)
    {
        message = _message;
        return message;
    }

    [DataMemberAttribute('CustomerId')]
    public str parmCustomerId(str _customerId = customerId)
    {
        customerId = _customerId;
        return customerId;
    }

    [DataMemberAttribute('CustomerList'),
     AifCollectionTypeAttribute('CustomerList', Types::Class, classStr(CustomerInfoRequest))]
    public List parmCustomerList(List _customerList = customerList)
    {
        customerList = _customerList;
        return customerList;
    }
}
```

## 3. Create the Service Class

```xpp
/// <summary>
/// Custom REST service for customer operations
/// </summary>
class CustomerRestService
{
    /// <summary>
    /// Gets customer information by account number
    /// </summary>
    /// <param name="_customerAccount">Customer account number</param>
    /// <returns>CustomerInfoResponse with customer details</returns>
    [AifCollectionTypeAttribute('return', Types::Class, classStr(CustomerInfoResponse))]
    public CustomerInfoResponse getCustomerByAccount(str _customerAccount)
    {
        CustomerInfoResponse response = new CustomerInfoResponse();
        CustTable custTable;

        try
        {
            select firstonly custTable
                where custTable.AccountNum == _customerAccount;

            if (custTable)
            {
                response.parmSuccess(true);
                response.parmMessage('Customer found successfully');
                response.parmCustomerId(custTable.AccountNum);

                // Create customer info
                CustomerInfoRequest customerInfo = new CustomerInfoRequest();
                customerInfo.parmCustomerAccount(custTable.AccountNum);
                customerInfo.parmCustomerName(custTable.name());
                customerInfo.parmCustomerGroup(custTable.CustGroup);

                List customerList = new List(Types::Class);
                customerList.addEnd(customerInfo);
                response.parmCustomerList(customerList);
            }
            else
            {
                response.parmSuccess(false);
                response.parmMessage(strFmt('Customer with account %1 not found', _customerAccount));
            }
        }
        catch (Exception::Error)
        {
            response.parmSuccess(false);
            response.parmMessage('An error occurred while retrieving customer information');
        }

        return response;
    }

    /// <summary>
    /// Gets all customers by customer group
    /// </summary>
    /// <param name="_customerGroup">Customer group ID</param>
    /// <returns>CustomerInfoResponse with list of customers</returns>
    [AifCollectionTypeAttribute('return', Types::Class, classStr(CustomerInfoResponse))]
    public CustomerInfoResponse getCustomersByGroup(str _customerGroup)
    {
        CustomerInfoResponse response = new CustomerInfoResponse();
        CustTable custTable;
        List customerList = new List(Types::Class);
        int recordCount = 0;

        try
        {
            while select custTable
                where custTable.CustGroup == _customerGroup
            {
                CustomerInfoRequest customerInfo = new CustomerInfoRequest();
                customerInfo.parmCustomerAccount(custTable.AccountNum);
                customerInfo.parmCustomerName(custTable.name());
                customerInfo.parmCustomerGroup(custTable.CustGroup);
                customerList.addEnd(customerInfo);
                recordCount++;
            }

            if (recordCount > 0)
            {
                response.parmSuccess(true);
                response.parmMessage(strFmt('%1 customers found in group %2', recordCount, _customerGroup));
                response.parmCustomerList(customerList);
            }
            else
            {
                response.parmSuccess(false);
                response.parmMessage(strFmt('No customers found in group %1', _customerGroup));
            }
        }
        catch (Exception::Error)
        {
            response.parmSuccess(false);
            response.parmMessage('An error occurred while retrieving customers');
        }

        return response;
    }

    /// <summary>
    /// Creates a new customer
    /// </summary>
    /// <param name="_request">CustomerInfoRequest with customer details</param>
    /// <returns>CustomerInfoResponse with operation result</returns>
    [AifCollectionTypeAttribute('return', Types::Class, classStr(CustomerInfoResponse))]
    public CustomerInfoResponse createCustomer(CustomerInfoRequest _request)
    {
        CustomerInfoResponse response = new CustomerInfoResponse();
        CustTable custTable;

        try
        {
            ttsbegin;

            // Check if customer already exists
            select firstonly custTable
                where custTable.AccountNum == _request.parmCustomerAccount();

            if (custTable)
            {
                response.parmSuccess(false);
                response.parmMessage(strFmt('Customer %1 already exists', _request.parmCustomerAccount()));
            }
            else
            {
                // Create new customer
                custTable.clear();
                custTable.AccountNum = _request.parmCustomerAccount();
                custTable.CustGroup = _request.parmCustomerGroup();

                // Set the party name through DirPartyTable
                DirPartyTable dirPartyTable;
                dirPartyTable.Name = _request.parmCustomerName();
                dirPartyTable.insert();

                custTable.Party = dirPartyTable.RecId;
                custTable.insert();

                response.parmSuccess(true);
                response.parmMessage(strFmt('Customer %1 created successfully', _request.parmCustomerAccount()));
                response.parmCustomerId(custTable.AccountNum);
            }

            ttscommit;
        }
        catch (Exception::Error)
        {
            ttsabort;
            response.parmSuccess(false);
            response.parmMessage('An error occurred while creating the customer');
        }

        return response;
    }

    /// <summary>
    /// Updates an existing customer
    /// </summary>
    /// <param name="_request">CustomerInfoRequest with updated details</param>
    /// <returns>CustomerInfoResponse with operation result</returns>
    [AifCollectionTypeAttribute('return', Types::Class, classStr(CustomerInfoResponse))]
    public CustomerInfoResponse updateCustomer(CustomerInfoRequest _request)
    {
        CustomerInfoResponse response = new CustomerInfoResponse();
        CustTable custTable;

        try
        {
            ttsbegin;

            select forupdate custTable
                where custTable.AccountNum == _request.parmCustomerAccount();

            if (custTable)
            {
                custTable.CustGroup = _request.parmCustomerGroup();
                custTable.update();

                // Update party name if provided
                if (_request.parmCustomerName())
                {
                    DirPartyTable dirPartyTable;
                    select forupdate dirPartyTable
                        where dirPartyTable.RecId == custTable.Party;

                    if (dirPartyTable)
                    {
                        dirPartyTable.Name = _request.parmCustomerName();
                        dirPartyTable.update();
                    }
                }

                response.parmSuccess(true);
                response.parmMessage(strFmt('Customer %1 updated successfully', _request.parmCustomerAccount()));
                response.parmCustomerId(custTable.AccountNum);
            }
            else
            {
                response.parmSuccess(false);
                response.parmMessage(strFmt('Customer %1 not found', _request.parmCustomerAccount()));
            }

            ttscommit;
        }
        catch (Exception::Error)
        {
            ttsabort;
            response.parmSuccess(false);
            response.parmMessage('An error occurred while updating the customer');
        }

        return response;
    }

    /// <summary>
    /// Deletes a customer
    /// </summary>
    /// <param name="_customerAccount">Customer account to delete</param>
    /// <returns>CustomerInfoResponse with operation result</returns>
    [AifCollectionTypeAttribute('return', Types::Class, classStr(CustomerInfoResponse))]
    public CustomerInfoResponse deleteCustomer(str _customerAccount)
    {
        CustomerInfoResponse response = new CustomerInfoResponse();
        CustTable custTable;

        try
        {
            ttsbegin;

            select forupdate custTable
                where custTable.AccountNum == _customerAccount;

            if (custTable)
            {
                custTable.delete();
                response.parmSuccess(true);
                response.parmMessage(strFmt('Customer %1 deleted successfully', _customerAccount));
            }
            else
            {
                response.parmSuccess(false);
                response.parmMessage(strFmt('Customer %1 not found', _customerAccount));
            }

            ttscommit;
        }
        catch (Exception::Error)
        {
            ttsabort;
            response.parmSuccess(false);
            response.parmMessage('An error occurred while deleting the customer');
        }

        return response;
    }
}
```

## 4. Create the Service Group and Service (AOT Configuration)

### Service Definition (XML for reference)

```xml
<?xml version="1.0" encoding="utf-8"?>
<AxService xmlns:i="http://www.w3.org/2001/XMLSchema-instance">
    <Name>CustomerRestService</Name>
    <ServiceClass>CustomerRestService</ServiceClass>
    <ExternalName>CustomerRestService</ExternalName>
    <Description>Custom REST Service for Customer Operations</Description>
</AxService>
```

### Service Group Definition

```xml
<?xml version="1.0" encoding="utf-8"?>
<AxServiceGroup xmlns:i="http://www.w3.org/2001/XMLSchema-instance">
    <Name>CustomerServiceGroup</Name>
    <AutoDeploy>Yes</AutoDeploy>
    <Services>
        <Service>CustomerRestService</Service>
    </Services>
</AxServiceGroup>
```

## 5. Alternative: Custom HTTP Action Controller (D365FO)

For more RESTful control, create a custom controller:

```xpp
using System.Net;
using Microsoft.Dynamics.Platform.Integration.Services.OData;

/// <summary>
/// Custom API controller for customer operations
/// </summary>
[RoutePrefix("api/customers")]
public class CustomerApiController extends ODataController
{
    /// <summary>
    /// GET: api/customers/{accountNum}
    /// </summary>
    [HttpGet]
    [Route("{accountNum}")]
    public CustomerInfoResponse getCustomer(str accountNum)
    {
        CustomerRestService service = new CustomerRestService();
        return service.getCustomerByAccount(accountNum);
    }

    /// <summary>
    /// GET: api/customers/group/{groupId}
    /// </summary>
    [HttpGet]
    [Route("group/{groupId}")]
    public CustomerInfoResponse getCustomersByGroup(str groupId)
    {
        CustomerRestService service = new CustomerRestService();
        return service.getCustomersByGroup(groupId);
    }

    /// <summary>
    /// POST: api/customers
    /// </summary>
    [HttpPost]
    [Route("")]
    public CustomerInfoResponse createCustomer(CustomerInfoRequest request)
    {
        CustomerRestService service = new CustomerRestService();
        return service.createCustomer(request);
    }

    /// <summary>
    /// PUT: api/customers
    /// </summary>
    [HttpPut]
    [Route("")]
    public CustomerInfoResponse updateCustomer(CustomerInfoRequest request)
    {
        CustomerRestService service = new CustomerRestService();
        return service.updateCustomer(request);
    }

    /// <summary>
    /// DELETE: api/customers/{accountNum}
    /// </summary>
    [HttpDelete]
    [Route("{accountNum}")]
    public CustomerInfoResponse deleteCustomer(str accountNum)
    {
        CustomerRestService service = new CustomerRestService();
        return service.deleteCustomer(accountNum);
    }
}
```

## 6. Service Endpoints

Once deployed, the service will be available at:

| Method | Endpoint | Description |
|--------|----------|-------------|
| GET | `/api/services/CustomerServiceGroup/CustomerRestService/getCustomerByAccount?_customerAccount=CUST001` | Get customer by account |
| GET | `/api/services/CustomerServiceGroup/CustomerRestService/getCustomersByGroup?_customerGroup=10` | Get customers by group |
| POST | `/api/services/CustomerServiceGroup/CustomerRestService/createCustomer` | Create customer |
| POST | `/api/services/CustomerServiceGroup/CustomerRestService/updateCustomer` | Update customer |
| POST | `/api/services/CustomerServiceGroup/CustomerRestService/deleteCustomer?_customerAccount=CUST001` | Delete customer |

## 7. Sample JSON Request/Response

### Create Customer Request:
```json
{
    "CustomerAccount": "CUST001",
    "CustomerName": "Contoso Ltd",
    "CustomerGroup": "10"
}
```

### Response:
```json
{
    "Success": true,
    "Message": "Customer CUST001 created successfully",
    "CustomerId": "CUST001",
    "CustomerList": null
}
```

## 8. Authentication

For external calls, use OAuth 2.0 authentication with Azure AD. The service URL pattern is:

```
https://{environment}.operations.dynamics.com/api/services/{ServiceGroup}/{Service}/{Operation}
```

